@page "/profile"
@rendermode InteractiveAuto
@using Microsoft.AspNetCore.Components.Authorization
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Profile</PageTitle>

<h1>Profile</h1>

@if (_email is not null)
{
    <p><strong>Name:</strong> @_email</p>
    <h3>Roles</h3>
    <ul>
        @foreach (var role in _roles)
        {
            <li>@role</li>
        }
    </ul>
}
else
{
    <p>Not authenticated.</p>
}

@code {
    private string? _email;
    private string[] _roles = [];

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var user = authState.User;

        if (user.Identity?.IsAuthenticated == true)
        {
            _email = user.Identity.Name;
            _roles = user.FindAll(System.Security.Claims.ClaimTypes.Role)
                         .Select(c => c.Value)
                         .ToArray();
        }
    }
}

@page "/editor"
@rendermode InteractiveAuto
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Authorize(Roles = "Editor")]

<PageTitle>Editor</PageTitle>

<h1>Editor Page</h1>
<p>Welcome to the Editor page. You have the "Editor" role.</p>

@page "/viewer"
@rendermode InteractiveAuto
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Authorize]

<PageTitle>Viewer</PageTitle>

<h1>Viewer Page</h1>
<p>Welcome! This page is accessible to any authenticated user.</p>

